function relativeAge(time){const hours=Math.max(0,(Date.now()-time)/3600000);return hours<1?'kurang dari 1 jam lalu':'sekitar '+Math.floor(hours)+' jam lalu';}
function updateCheckedTime(){if(state.checkedAt&&!state.busy){const times=CachedData.status(['hotspot-High','hotspot-Medium','hotspot-Low','air-main','weather-main','forecast-main','forecast-villages']).items.map(r=>r.updatedAt).filter(t=>Number.isFinite(Date.parse(t))).sort();$('lastUpdate').textContent=WeatherUI.generalUpdateText(times[0]);}}
'use strict';
const $=id=>document.getElementById(id);

const DISTRICTS=['Banama Tingang','Jabiren Raya','Kahayan Hilir','Kahayan Kuala','Kahayan Tengah','Maliku','Pandih Batu','Sebangau Kuala'];
const LEVELS=['High','Medium','Low'], COLORS={High:'#c95635',Medium:'#d4a340',Low:'#6a9972'}, NAMES={High:'Tinggi',Medium:'Sedang',Low:'Rendah'};
const state={raw:[],filtered:[],page:0,loaded:false,partial:false,map:null,markers:null,markerIndex:[],busy:false};
const fmt=n=>new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(n);
const esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const wib=(d=new Date())=>new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',dateStyle:'medium',timeStyle:'short'}).format(d)+' WIB';
const wibISO=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date()).replace(' ','T');
function confidence(v,fallback){if(v==null||v==='')return fallback;const s=String(v).trim().toLowerCase(),n=Number(s);if(Number.isFinite(n))return n>=80?'High':n>=30?'Medium':'Low';if(s.startsWith('h'))return 'High';if(s.startsWith('l'))return 'Low';if(s.startsWith('m')||s.startsWith('n'))return 'Medium';return fallback;}
function normalizeKab(s){return String(s??'').toLowerCase().replace(/^kabupaten\s+|^kab\.\s*/,'').trim().replace(/\s+/g,' ');}
async function json(url){const res=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(25000)});if(!res.ok)throw Error('HTTP '+res.status);return res.json();}
function initMap(){if(!window.L){$('map').innerHTML='<div class="map-loading error">Peta belum dapat dimuat. Data tetap tersedia dalam tabel.</div>';return;}
 $('map').replaceChildren();state.map=L.map('map',{scrollWheelZoom:false,touchZoom:true}).setView([-2.75,114.23],11);
 L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:18}).addTo(state.map);
 state.markers=L.layerGroup().addTo(state.map);
}
function focus(){if(!state.map)return;if(state.filtered.length)state.map.fitBounds(state.filtered.map(x=>[x.lat,x.lon]),{padding:[35,35],maxZoom:11});else state.map.setView([-2.45,114.05],8);}
function replaceOptions(id,values,first){const old=$(id).value;$(id).replaceChildren(new Option(first,''),...values.map(v=>new Option(v,v)));if(values.includes(old))$(id).value=old;}
function detectionTime(s){return Date.parse(s.replace(' WIB','+07:00').replace(' ','T'));}
function inPeriod(r,period,now=state.filterNow||Date.now()){if(period==='24h'||period==='48h'){const t=detectionTime(r.when);return Number.isFinite(t)&&t>=now-Number.parseInt(period)*3600000&&t<=now;}return !period||r.when.startsWith(period);}
function periodOptions(id,dates){const old=$(id).value;$(id).replaceChildren(new Option('24 jam terakhir','24h'),new Option('48 jam terakhir','48h'),new Option('Semua tanggal dalam feed',''),...dates.map(d=>new Option(d+' · 00.00–23.59 WIB',d)));$(id).value=state.initialDate?old:'24h';}
function periodLabel(){const p=$('date').value;return p==='24h'||p==='48h'?p.replace('h',' jam terakhir')+' · hingga '+wib(new Date(state.filterNow||Date.now())):p?p+' · 00.00–23.59 WIB':'Semua tanggal yang tersedia dalam feed';}
async function hotspots(){
 state.filterNow=Date.now();setLoad('hotspots','loading','Memuat titik panas…');setLoad('regions','loading','Memuat rekap wilayah…');
 const results=await Promise.allSettled(LEVELS.map(level=>CachedData.get('hotspot-'+level)));
 state.raw=[];state.allRaw=[];const timestamps=[];let good=0;
 results.forEach((r,i)=>{if(r.status!=='fulfilled'||!Array.isArray(r.value?.data?.features))return;good++;const j=r.value;timestamps.push(LEVELS[i]+': '+(j.generated_at||'waktu tidak tersedia'));
 for(const f of j.data.features){const p=f.properties||{},c=f.geometry?.coordinates;if(!Array.isArray(c)||!Number.isFinite(c[0])||!Number.isFinite(c[1])||Math.abs(c[0])>180||Math.abs(c[1])>90)continue;const record={kab:p.kabupaten||'Tidak diketahui',lat:c[1],lon:c[0],desa:p.desa||'Tidak diketahui',kec:String(p.kecamatan||'').trim().toLowerCase()==='jabiren'?'Jabiren Raya':p.kecamatan||'Tidak diketahui',sat:p.satelit||'Tidak diketahui',when:p.date_hotspot||'',level:confidence(p.confidence,LEVELS[i])};state.allRaw.push(record);if(normalizeKab(p.kabupaten)==='pulang pisau')state.raw.push(record);}});
 state.loaded=good>0;state.partial=good<3;state.sourceDates=results.filter(r=>r.status==='fulfilled').map(r=>r.value.generated_at).filter(Boolean);setLoad('hotspots',good===3?'ready':'error',good?'Sebagian sumber belum tersedia. Angka berasal dari data yang berhasil dimuat.':'Data titik panas belum tersedia.');setLoad('regions',good===3?'ready':'error',good?'Sebagian sumber rekap belum tersedia.':'Rekap wilayah belum tersedia.');updateFreshness();
 state.raw.sort((a,b)=>b.when.localeCompare(a.when));
 periodOptions('date',[...new Set(state.allRaw.map(r=>r.when.slice(0,10)).filter(Boolean))].sort().reverse());
 replaceOptions('district',[...new Set([...DISTRICTS,...state.raw.map(x=>x.kec)])].sort(),'Semua kecamatan');
 $('sourceTimes').textContent='Waktu pembentukan feed (sesuai sumber): '+timestamps.join(' · ');
 const stale=results.some(r=>r.status==='fulfilled'&&r.value.generated_at&&(Date.now()-Date.parse(r.value.generated_at)>24*3600000));

 $('hotMeta').textContent=state.loaded?'Deteksi satelit · sesuai filter aktif':'Tidak tersedia · bukan berarti nol';
 CachedData.mark('hotspots',LEVELS.map(l=>'hotspot-'+l));CachedData.mark('regions',LEVELS.map(l=>'hotspot-'+l));state.page=0;render();if(typeof updateRegions==='function'){updateRegions();await loadVillagePM();}
}
function render(){state.filtered=state.raw.filter(r=>(!state.selectedVillage||villageKey(r)===state.selectedVillage)&&(!$('district').value||r.kec===$('district').value)&&inPeriod(r,$('date').value)&&(!$('confidence').value||r.level===$('confidence').value)&&(!String($('search').value).trim()||r.desa.toLowerCase().includes($('search').value.trim().toLowerCase())));
 $('total').textContent=state.loaded?fmt(state.filtered.length):'—';$('high').textContent=state.loaded?fmt(state.filtered.filter(r=>r.level==='High').length):'—';
 $('mapCount').textContent=state.loaded?`${fmt(state.filtered.length)} deteksi`:'Data tidak tersedia';
 const sourceTimes=(state.sourceDates||[]).map(Date.parse).filter(Number.isFinite);const updated=sourceTimes.length?wib(new Date(Math.min(...sourceTimes))):'Belum tersedia';const selectedPeriod=$('date').value;const shortPeriod=selectedPeriod==='24h'?'24 jam terakhir':selectedPeriod==='48h'?'48 jam terakhir':selectedPeriod||'Semua tanggal feed';$('hotMeta').textContent='Pembaruan sumber '+updated; $('periodStatus').textContent=periodLabel();
 if(state.markers){state.markers.clearLayers();state.markerIndex=[];for(const r of state.filtered){const marker=L.circleMarker([r.lat,r.lon],{radius:5,weight:1,color:'#fff',fillColor:COLORS[r.level],fillOpacity:.85}).bindPopup(`<b>${esc(r.desa)}</b><br>${esc(r.kec)}<br>${esc(r.when)}<br>${esc(r.sat)} · ${NAMES[r.level]}<br>${r.lat.toFixed(5)}, ${r.lon.toFixed(5)}`);if(typeof extras==='undefined'||extras.layers[r.level])marker.addTo(state.markers);state.markerIndex.push(marker);}}
 const counts=new Map(DISTRICTS.map(x=>[x,0]));for(const r of state.filtered)counts.set(r.kec,(counts.get(r.kec)||0)+1);
 $('districtTotal').textContent=state.loaded?'Total '+fmt([...counts.values()].reduce((sum,n)=>sum+n,0))+' titik terdeteksi':'Total belum tersedia'; const max=Math.max(1,...counts.values());$('districtBars').innerHTML=state.loaded?[...counts].sort((a,b)=>b[1]-a[1]).map(([name,n])=>`<div class="bar-row"><span>${esc(name)}</span><div class="bar-track"><i style="width:${n/max*100}%"></i></div><b>${fmt(n)}</b></div>`).join(''):'Data hotspot tidak tersedia.';
 document.dispatchEvent(new Event('sipantip:hotspots'));updateActiveFilters();renderTable();if(typeof renderVillage==='function'){renderVillage();renderMapExtras();renderVillageSelection();}
}
function renderTable(){const size=10,pages=Math.max(1,Math.ceil(state.filtered.length/size));state.page=Math.min(state.page,pages-1);const start=state.page*size;
 $('rows').innerHTML=state.filtered.slice(start,start+size).map((r,i)=>`<tr><td>${esc(r.desa)}</td><td>${esc(r.kec)}</td><td>${esc(r.when||'Tidak tersedia')}</td><td><span class="tag ${r.level}">${NAMES[r.level]}</span></td><td><button class="loc" data-index="${start+i}" aria-label="Lihat lokasi ${esc(r.desa)}">Lihat ↗</button></td></tr>`).join('')||`<tr><td colspan="5">${state.loaded?(state.partial?'Data belum lengkap; belum ada deteksi pada feed yang tersedia.':'Tidak ada deteksi yang sesuai filter.'):'Data tidak tersedia. Periksa koneksi lalu klik Refresh data.'}</td></tr>`;
 $('tableCount').textContent=`${fmt(state.filtered.length)} rekaman${state.partial?' · feed belum lengkap':''}`;$('pageInfo').textContent=`Halaman ${state.page+1} dari ${pages}`;$('prev').disabled=state.page===0;$('next').disabled=state.page>=pages-1;
}
async function air(){setLoad('air','loading','Memuat estimasi udara…');try{const j=await CachedData.get('air-main');const h=j.hourly;if(!h?.time?.length)throw Error('Tidak ada data');const now=wibISO();let i=-1;h.time.forEach((t,n)=>{if(t<=now)i=n;});if(i<0)throw Error('Tidak ada data saat ini');state.airSource=h.time[i];updateFreshness();CachedData.mark('air',['air-main']);const a=h.us_aqi[i],p=h.pm2_5[i];$('aqi').textContent=Number.isFinite(a)?fmt(a):'—';$('pm').textContent=Number.isFinite(p)?fmt(p):'—';const cats=['Baik','Sedang','Tidak sehat bagi kelompok sensitif','Tidak sehat','Sangat tidak sehat','Berbahaya'];$('aqiLabel').textContent=Number.isFinite(a)?cats[a<=50?0:a<=100?1:a<=150?2:a<=200?3:a<=300?4:5]:'Tidak tersedia';plot(h.time.slice(Math.max(0,i-23),i+1),h.pm2_5.slice(Math.max(0,i-23),i+1),h.us_aqi.slice(Math.max(0,i-23),i+1));}catch(e){$('aqi').textContent='—';$('pm').textContent='—';$('aqiLabel').textContent='Model tidak tersedia';$('chart').textContent='Data PM 2.5 belum tersedia.';setLoad('air','error',CachedData.errorText(e));}}
async function visibility(){try{const j=await CachedData.get('weather-main'),h=j.hourly;let i=-1;const now=wibISO();h?.time?.forEach((t,n)=>{if(t<=now)i=n;});const v=h?.visibility?.[i];if(i<0||!Number.isFinite(v)||v<0)throw Error('Data tidak tersedia');WeatherUI.renderVisibility(v,h.time[i]+':00+07:00');}catch(e){WeatherUI.renderVisibility(null,null);}}
async function weather(){setLoad('weather','loading','Memuat angin…');try{const j=await CachedData.get('weather-main');const c=j.current;if(!c||!Number.isFinite(c.wind_speed_10m))throw Error('Tidak ada data');CachedData.mark('weather',['weather-main','weather-grid']);$('wind').textContent=fmt(c.wind_speed_10m);$('direction').textContent=Number.isFinite(c.wind_direction_10m)?`Dari ${['utara','timur laut','timur','tenggara','selatan','barat daya','barat','barat laut'][Math.round(c.wind_direction_10m/45)%8]} · ${c.wind_direction_10m}°`:'Arah tidak tersedia';}catch(e){$('wind').textContent='—';$('direction').textContent='Model angin tidak tersedia';setLoad('weather','error',CachedData.errorText(e));}}
async function refresh(){if(state.busy)return;if(state.lastRead&&Date.now()-state.lastRead<60000){$('lastUpdate').textContent='Data sudah diperiksa. Refresh berikutnya tersedia dalam satu menit.';return;}state.lastRead=Date.now();state.busy=true;$('refresh').disabled=true;$('lastUpdate').textContent='Memuat data terbaru…';await Promise.allSettled([hotspots(),air(),weather(),visibility(),window.RainForecast?.load(),typeof loadGrid==='function'?loadGrid():null,typeof loadDaily==='function'?loadDaily():null]);const n=Number($('aqi').textContent.replace(/\./g,'').replace(',','.'));const card=$('aqi').closest('.metric');if(card){const band=!Number.isFinite(n)?6:n<=50?0:n<=100?1:n<=150?2:n<=200?3:n<=300?4:5;card.style.background=['#e5eedf','#f6f0d7','#f8e9d9','#f8e1df','#eee1f1','#ecdce2','#edf0eb'][band];$('aqiLabel').style.background=['#d3e6c8','#efe0a7','#edc89d','#edbbb7','#dbc2e2','#d9b5c3','#e0e5dd'][band];} CachedData.render();state.checkedAt=Date.now();$('refresh').disabled=false;state.busy=false;updateCheckedTime();}
for(const id of ['district','date','confidence'])$(id).addEventListener('change',()=>{state.page=0;if(id==='district')state.selectedVillage=null;if(id==='date'){$('regencyDate').value=$('date').value;renderRegions();}render();});
$('search').addEventListener('input',()=>{state.page=0;render();});$('prev').onclick=()=>{state.page--;renderTable();};$('next').onclick=()=>{state.page++;renderTable();};
$('rows').onclick=e=>{const b=e.target.closest('[data-index]');if(!b||!state.map)return;const i=Number(b.dataset.index),r=state.filtered[i];state.map.setView([r.lat,r.lon],13);state.markerIndex[i]?.openPopup();$('peta-section').scrollIntoView({behavior:'smooth'});};
$('resetMap').onclick=focus;$('refresh').onclick=refresh;
$('clock').textContent=wib();initMap();refresh();setInterval(()=>{if(!document.hidden)refresh();},600000);

setInterval(()=>{updateCheckedTime();$('clock').textContent=wib();},60000);
